"""FastAPI service exposing a guarded deep agent."""

from __future__ import annotations

import hmac
import logging
from typing import Annotated

from fastapi import APIRouter, Depends, FastAPI, Header, HTTPException, Request, Response
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from langchain_core.language_models import BaseChatModel
from pydantic import BaseModel, ValidationError

from app.agent import GuardedAgent, build_model
from app.config import Settings
from app.guardrails import TOPIC_BLOCKLIST
from app.policies import DEFAULT_TENANT, InMemoryPolicyStore, PolicyStore, TenantPolicy, effective_policy

logger = logging.getLogger(__name__)


class ChatRequest(BaseModel):
    session_id: str
    message: str


class GuardrailAction(BaseModel):
    name: str
    action: str


class ChatResponse(BaseModel):
    session_id: str
    reply: str
    guardrails: list[GuardrailAction]


def tenant_id_from_header(x_tenant_id: Annotated[str | None, Header()] = None) -> str:
    """The calling tenant: the `X-Tenant-ID` header, or "default" when absent or blank."""
    if x_tenant_id is None or not x_tenant_id.strip():
        return DEFAULT_TENANT
    return x_tenant_id


def policy_store(request: Request) -> PolicyStore:
    return request.app.state.policy_store


Store = Annotated[PolicyStore, Depends(policy_store)]


def admin_router(admin_api_key: str | None, default_policy: TenantPolicy) -> APIRouter:
    def require_admin(x_admin_key: Annotated[str | None, Header()] = None) -> None:
        # Fails closed: with no ADMIN_API_KEY configured, nobody is an admin.
        if (
            not admin_api_key
            or x_admin_key is None
            or not hmac.compare_digest(x_admin_key.encode(), admin_api_key.encode())
        ):
            raise HTTPException(status_code=401, detail="invalid or missing admin key")

    router = APIRouter(prefix="/tenants/{tenant_id}/policy", dependencies=[Depends(require_admin)])

    @router.get("", response_model=TenantPolicy, responses={401: {"description": "Bad admin key"}})
    async def get_policy(tenant_id: str, store: Store) -> TenantPolicy:
        return await effective_policy(store, tenant_id, default_policy)

    # The body is parsed by hand, after `require_admin`, so a request without a
    # valid admin key always gets 401, even when its body is also invalid.
    @router.put(
        "",
        response_model=TenantPolicy,
        responses={401: {"description": "Bad admin key"}},
        openapi_extra={
            "requestBody": {
                "required": True,
                "content": {"application/json": {"schema": TenantPolicy.model_json_schema()}},
            }
        },
    )
    async def put_policy(tenant_id: str, request: Request, store: Store) -> TenantPolicy:
        try:
            policy = TenantPolicy.model_validate_json(await request.body())
        except ValidationError as exc:
            raise RequestValidationError(exc.errors(include_url=False, include_context=False)) from None
        await store.put(tenant_id, policy)
        return policy

    @router.delete("", status_code=204, responses={401: {"description": "Bad admin key"}})
    async def delete_policy(tenant_id: str, store: Store) -> Response:
        await store.delete(tenant_id)
        return Response(status_code=204)

    return router


def create_app(model: BaseChatModel | None = None) -> FastAPI:
    settings = Settings.from_env()
    if model is None:
        model = build_model(settings)
    agent = GuardedAgent(model, settings)

    app = FastAPI(title="Deep agent service")
    # Swap for a database-backed `PolicyStore` to persist policies.
    app.state.policy_store = InMemoryPolicyStore()
    app.include_router(admin_router(settings.admin_api_key, agent.default_policy))

    @app.get("/health")
    async def health() -> dict[str, str]:
        return {"status": "ok"}

    @app.post(
        "/chat",
        response_model=ChatResponse,
        responses={403: {"description": "Blocked by a guardrail"}, 502: {"description": "Agent failure"}},
    )
    async def chat(
        request: ChatRequest,
        tenant_id: Annotated[str, Depends(tenant_id_from_header)],
        store: Store,
    ) -> ChatResponse | JSONResponse:
        try:
            policy = await effective_policy(store, tenant_id, agent.default_policy)
            result = await agent.run_turn(request.message, policy)
        except Exception:
            logger.exception("agent turn failed for tenant %r session %s", tenant_id, request.session_id)
            return JSONResponse(status_code=502, content={"error": "agent_error"})
        if result.blocked:
            return JSONResponse(status_code=403, content={"error": "blocked", "guardrail": TOPIC_BLOCKLIST})
        return ChatResponse(
            session_id=request.session_id,
            reply=result.reply,
            guardrails=[GuardrailAction(**g) for g in result.guardrails],
        )

    return app
"""Builds the deep agent and runs one guarded conversational turn."""

from __future__ import annotations

from collections.abc import Awaitable, Callable, Iterator
from contextlib import contextmanager
from contextvars import ContextVar
from dataclasses import dataclass, field
from functools import lru_cache
from typing import Any

from deepagents import create_deep_agent
from deepagents.middleware.subagents import GENERAL_PURPOSE_SUBAGENT
from langchain.agents.middleware import AgentMiddleware
from langchain.chat_models import init_chat_model
from langchain_core.language_models import BaseChatModel
from langchain_core.messages import AIMessage, SystemMessage

from app.config import Settings
from app.guardrails import (
    PII_REDACTION,
    TOOL_CALL_LIMIT,
    TOPIC_BLOCKLIST,
    ToolCallLimitExceeded,
    TopicBlocklist,
    TurnToolCallLimitMiddleware,
    redact_pii,
    tool_call_budget,
)
from app.policies import TenantPolicy
from app.tools import TOOLS


def build_model(settings: Settings) -> BaseChatModel:
    return init_chat_model(settings.model)


# --- Tenant instructions ------------------------------------------------------

_turn_instructions: ContextVar[str | None] = ContextVar("turn_instructions", default=None)


@contextmanager
def turn_instructions(text: str | None) -> Iterator[None]:
    """Scope extra system instructions (a tenant's system prompt) to one turn."""
    token = _turn_instructions.set(text)
    try:
        yield
    finally:
        _turn_instructions.reset(token)


class TurnInstructionsMiddleware(AgentMiddleware):
    """Appends the turn's extra instructions to the system message of every model call.

    The agent is built once and shared by all tenants, so the instructions come
    from a ContextVar set per turn rather than from the agent's own prompt.
    """

    name = "TurnInstructionsMiddleware"

    def _apply(self, request: Any) -> Any:
        extra = _turn_instructions.get()
        if not extra:
            return request
        system = request.system_message
        if system is None:
            content: str | list[Any] = extra
        elif isinstance(system.content, str):
            content = f"{system.content}\n\n{extra}"
        else:
            content = [*system.content, {"type": "text", "text": extra}]
        return request.override(system_message=SystemMessage(content=content))

    def wrap_model_call(self, request: Any, handler: Callable[[Any], Any]) -> Any:
        return handler(self._apply(request))

    async def awrap_model_call(self, request: Any, handler: Callable[[Any], Awaitable[Any]]) -> Any:
        return await handler(self._apply(request))


def build_agent(model: BaseChatModel, settings: Settings) -> Any:
    # deepagents does not pass custom middleware on to subagents, so the
    # general-purpose subagent is declared explicitly with the same middleware.
    # Both draw from the same per-turn budget (see `tool_call_budget`) and get
    # the same tenant instructions. Any subagent added here must include them too.
    def middleware() -> list[AgentMiddleware]:
        return [TurnToolCallLimitMiddleware(), TurnInstructionsMiddleware()]

    general_purpose = {**GENERAL_PURPOSE_SUBAGENT, "middleware": middleware()}
    return create_deep_agent(
        model=model,
        tools=TOOLS,
        system_prompt=settings.system_prompt,
        middleware=middleware(),
        subagents=[general_purpose],
    )


@lru_cache(maxsize=256)
def _blocklist(topics: tuple[str, ...]) -> TopicBlocklist:
    return TopicBlocklist(topics)


@dataclass
class TurnResult:
    reply: str = ""
    guardrails: list[dict[str, str]] = field(default_factory=list)
    blocked: bool = False


class GuardedAgent:
    def __init__(self, model: BaseChatModel, settings: Settings) -> None:
        self.settings = settings
        self.default_policy = TenantPolicy.default(settings)
        self.agent = build_agent(model, settings)

    async def run_turn(self, message: str, policy: TenantPolicy | None = None) -> TurnResult:
        """Run one turn under `policy` (the default policy when None)."""
        policy = self.default_policy if policy is None else policy
        result = TurnResult()

        def acted(name: str, action: str) -> None:
            entry = {"name": name, "action": action}
            if entry not in result.guardrails:
                result.guardrails.append(entry)

        if _blocklist(tuple(policy.blocked_topics)).find(message):
            acted(TOPIC_BLOCKLIST, "blocked")
            result.blocked = True
            return result

        if policy.redact_pii:
            message, redacted = redact_pii(message)
            if redacted:
                acted(PII_REDACTION, "redacted")

        limit = policy.max_tool_calls
        try:
            with tool_call_budget(limit), turn_instructions(policy.system_prompt):
                state = await self.agent.ainvoke({"messages": [{"role": "user", "content": message}]})
        except ToolCallLimitExceeded:
            acted(TOOL_CALL_LIMIT, "stopped")
            result.reply = (
                f"I stopped working on this request because it reached the limit of "
                f"{limit} tool calls per message. Please try a simpler or narrower request."
            )
            return result

        reply = _final_reply(state)
        if policy.redact_pii:
            reply, redacted = redact_pii(reply)
            if redacted:
                acted(PII_REDACTION, "redacted")
        result.reply = reply
        return result


def _final_reply(state: dict[str, Any]) -> str:
    for msg in reversed(state.get("messages", [])):
        if isinstance(msg, AIMessage):
            return msg.text
    return ""
"""Guardrails: PII redaction, topic blocklist and a per-turn tool-call limit."""

from __future__ import annotations

import re
import threading
from collections.abc import Awaitable, Callable, Iterable, Iterator
from contextlib import contextmanager
from contextvars import ContextVar
from typing import Any

from langchain.agents.middleware import AgentMiddleware

PII_REDACTION = "pii_redaction"
TOPIC_BLOCKLIST = "topic_blocklist"
TOOL_CALL_LIMIT = "tool_call_limit"

REDACTED_EMAIL = "[REDACTED_EMAIL]"
REDACTED_PHONE = "[REDACTED_PHONE]"

# --- PII redaction ---------------------------------------------------------

_EMAIL_RE = re.compile(r"(?<![\w.+-])[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}\b")

# Candidate phone numbers: optional +country code, an area code (optionally in
# parentheses), then groups of digits separated by at most one space, dot or
# hyphen. Candidates are then checked by digit count in `_is_phone`.
_PHONE_RE = re.compile(
    r"(?<![\w+])"
    r"(?P<intl>\+\d{1,3}[ .-]?)?"
    r"(?:\(\d{1,4}\)|\d{1,4})"
    r"(?:[ .-]?\d{2,4}){1,4}"
    r"(?![\w])"
)


def _is_phone(match: re.Match[str]) -> bool:
    digits = sum(c.isdigit() for c in match.group())
    if match.group("intl"):
        return 8 <= digits <= 15
    # Without a country code, require a full national number (e.g. 10-digit
    # North American or 11-digit UK numbers). This keeps dates, years, prices
    # and short numbers from being redacted.
    return 10 <= digits <= 11


def redact_pii(text: str) -> tuple[str, bool]:
    """Replace emails and phone numbers. Returns the new text and whether anything changed."""
    redacted = _EMAIL_RE.sub(REDACTED_EMAIL, text)
    redacted = _PHONE_RE.sub(lambda m: REDACTED_PHONE if _is_phone(m) else m.group(), redacted)
    return redacted, redacted != text


# --- Topic blocklist -------------------------------------------------------


class TopicBlocklist:
    """Case-insensitive whole-word match against a list of topics (words or phrases)."""

    def __init__(self, topics: Iterable[str]) -> None:
        self.topics = tuple(t.strip() for t in topics if t.strip())
        if self.topics:
            alternatives = "|".join(
                r"\s+".join(re.escape(word) for word in topic.split())
                for topic in sorted(self.topics, key=len, reverse=True)
            )
            self._pattern: re.Pattern[str] | None = re.compile(
                rf"(?<!\w)(?:{alternatives})(?!\w)", re.IGNORECASE
            )
        else:
            self._pattern = None

    def find(self, text: str) -> str | None:
        """Return the first blocked topic mentioned in `text`, or None."""
        if self._pattern is None:
            return None
        match = self._pattern.search(text)
        return match.group() if match else None


# --- Tool-call limit -------------------------------------------------------


class ToolCallLimitExceeded(Exception):
    def __init__(self, limit: int) -> None:
        super().__init__(f"tool call limit of {limit} exceeded")
        self.limit = limit


class _TurnBudget:
    def __init__(self, limit: int) -> None:
        self.limit = limit
        self.used = 0
        self._lock = threading.Lock()

    def take(self) -> None:
        with self._lock:
            if self.used >= self.limit:
                raise ToolCallLimitExceeded(self.limit)
            self.used += 1


_current_budget: ContextVar[_TurnBudget | None] = ContextVar("tool_call_budget", default=None)


@contextmanager
def tool_call_budget(limit: int) -> Iterator[_TurnBudget]:
    """Scope a tool-call budget to one turn.

    The budget lives in a ContextVar holding a mutable counter, so tool calls
    made by subagents (which run inside the parent's `task` tool, in the same
    context) draw from the same budget as the main agent.
    """
    budget = _TurnBudget(limit)
    token = _current_budget.set(budget)
    try:
        yield budget
    finally:
        _current_budget.reset(token)


class TurnToolCallLimitMiddleware(AgentMiddleware):
    """Raises `ToolCallLimitExceeded` before running a tool call past the turn's budget.

    The exception is not caught by the tool node, so it ends the whole turn,
    including any subagent run that is in progress.
    """

    name = "TurnToolCallLimitMiddleware"

    def _take(self) -> None:
        budget = _current_budget.get()
        if budget is not None:
            budget.take()

    def wrap_tool_call(self, request: Any, handler: Callable[[Any], Any]) -> Any:
        self._take()
        return handler(request)

    async def awrap_tool_call(self, request: Any, handler: Callable[[Any], Awaitable[Any]]) -> Any:
        self._take()
        return await handler(request)
"""Per-tenant guardrail policies and where they are stored."""

from __future__ import annotations

from typing import Annotated, Protocol

from pydantic import BaseModel, ConfigDict, Field, StrictBool, StrictInt, StrictStr, field_validator

from app.config import Settings

DEFAULT_TENANT = "default"


class TenantPolicy(BaseModel):
    """Guardrail settings for one tenant.

    Types are strict (no "yes" for a bool, no "5" for an int) and unknown fields
    are rejected, so a typo in a policy cannot silently weaken a guardrail.
    """

    model_config = ConfigDict(extra="forbid", frozen=True)

    blocked_topics: list[StrictStr]
    redact_pii: StrictBool
    max_tool_calls: Annotated[StrictInt, Field(ge=0)]
    system_prompt: StrictStr | None

    @field_validator("blocked_topics")
    @classmethod
    def _no_blank_topics(cls, topics: list[str]) -> list[str]:
        if any(not t.strip() for t in topics):
            raise ValueError("blocked topics must not be blank")
        return topics

    @classmethod
    def default(cls, settings: Settings) -> TenantPolicy:
        """The policy for tenants without a stored one.

        With no environment overrides this is: blocked topics weapons and
        malware, PII redacted, 5 tool calls, no extra system prompt.
        `BLOCKED_TOPICS` and `MAX_TOOL_CALLS` still adjust it.
        """
        return cls(
            blocked_topics=list(settings.blocked_topics),
            redact_pii=True,
            max_tool_calls=settings.max_tool_calls,
            system_prompt=None,
        )


class PolicyStore(Protocol):
    """Storage for tenant policies. Async so a database-backed store can drop in."""

    async def get(self, tenant_id: str) -> TenantPolicy | None: ...

    async def put(self, tenant_id: str, policy: TenantPolicy) -> None: ...

    async def delete(self, tenant_id: str) -> None:
        """Remove the tenant's policy; a no-op if there is none."""
        ...


class InMemoryPolicyStore:
    def __init__(self) -> None:
        self._policies: dict[str, TenantPolicy] = {}

    async def get(self, tenant_id: str) -> TenantPolicy | None:
        return self._policies.get(tenant_id)

    async def put(self, tenant_id: str, policy: TenantPolicy) -> None:
        self._policies[tenant_id] = policy

    async def delete(self, tenant_id: str) -> None:
        self._policies.pop(tenant_id, None)


async def effective_policy(store: PolicyStore, tenant_id: str, default: TenantPolicy) -> TenantPolicy:
    policy = await store.get(tenant_id)
    return default if policy is None else policy
"""Service configuration, read from environment variables."""

from __future__ import annotations

import os
from collections.abc import Mapping
from dataclasses import dataclass, field

DEFAULT_MODEL = "anthropic:claude-sonnet-5-5"
DEFAULT_BLOCKED_TOPICS = ("weapons", "malware")
DEFAULT_MAX_TOOL_CALLS = 5
DEFAULT_SYSTEM_PROMPT = (
    "You are a helpful assistant. Use the calculator tool for arithmetic and "
    "the current_time tool when you need the date or time. Be concise."
)


@dataclass(frozen=True)
class Settings:
    model: str = DEFAULT_MODEL
    blocked_topics: tuple[str, ...] = DEFAULT_BLOCKED_TOPICS
    max_tool_calls: int = DEFAULT_MAX_TOOL_CALLS
    system_prompt: str = DEFAULT_SYSTEM_PROMPT
    # Key for the tenant policy endpoints. None (or empty) means they always return 401.
    admin_api_key: str | None = field(default=None, repr=False)

    @classmethod
    def from_env(cls, env: Mapping[str, str] | None = None) -> Settings:
        """Build settings from the environment.

        - `AGENT_MODEL`: `provider:model` string for `init_chat_model`.
        - `BLOCKED_TOPICS`: comma-separated list; an empty value disables the blocklist.
        - `MAX_TOOL_CALLS`: non-negative integer, tool calls allowed per turn.
        - `AGENT_SYSTEM_PROMPT`: system prompt for the agent.
        - `ADMIN_API_KEY`: key required by the tenant policy endpoints.
        """
        env = os.environ if env is None else env

        blocked = DEFAULT_BLOCKED_TOPICS
        if "BLOCKED_TOPICS" in env:
            blocked = tuple(t.strip() for t in env["BLOCKED_TOPICS"].split(",") if t.strip())

        max_tool_calls = DEFAULT_MAX_TOOL_CALLS
        if raw := env.get("MAX_TOOL_CALLS", "").strip():
            try:
                max_tool_calls = int(raw)
            except ValueError:
                raise ValueError(f"MAX_TOOL_CALLS must be an integer, got {raw!r}") from None
            if max_tool_calls < 0:
                raise ValueError(f"MAX_TOOL_CALLS must be >= 0, got {max_tool_calls}")

        return cls(
            model=env.get("AGENT_MODEL", "").strip() or DEFAULT_MODEL,
            blocked_topics=blocked,
            max_tool_calls=max_tool_calls,
            system_prompt=env.get("AGENT_SYSTEM_PROMPT", "").strip() or DEFAULT_SYSTEM_PROMPT,
            admin_api_key=env.get("ADMIN_API_KEY") or None,
        )
"""Tools given to the agent in addition to the deepagents built-ins."""

from __future__ import annotations

import ast
import math
import operator
from datetime import datetime
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from langchain_core.tools import tool

_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}
_UNARY_OPS = {ast.UAdd: operator.pos, ast.USub: operator.neg}
_FUNCTIONS = {"sqrt": math.sqrt, "abs": abs, "round": round, "log": math.log, "exp": math.exp}
_CONSTANTS = {"pi": math.pi, "e": math.e}
_MAX_EXPONENT = 1000


def evaluate(expression: str) -> float | int:
    """Safely evaluate an arithmetic expression (no names or calls beyond a small whitelist)."""

    def ev(node: ast.AST) -> float | int:
        match node:
            case ast.Expression(body=body):
                return ev(body)
            case ast.Constant(value=value) if isinstance(value, (int, float)) and not isinstance(value, bool):
                return value
            case ast.BinOp(left=left, op=op, right=right) if type(op) in _BIN_OPS:
                lhs, rhs = ev(left), ev(right)
                if isinstance(op, ast.Pow) and abs(rhs) > _MAX_EXPONENT:
                    raise ValueError("exponent too large")
                return _BIN_OPS[type(op)](lhs, rhs)
            case ast.UnaryOp(op=op, operand=operand) if type(op) in _UNARY_OPS:
                return _UNARY_OPS[type(op)](ev(operand))
            case ast.Name(id=name) if name in _CONSTANTS:
                return _CONSTANTS[name]
            case ast.Call(func=ast.Name(id=name), args=args, keywords=[]) if name in _FUNCTIONS:
                return _FUNCTIONS[name](*(ev(a) for a in args))
        raise ValueError(f"unsupported expression: {ast.unparse(node)}")

    return ev(ast.parse(expression, mode="eval"))


@tool
def calculator(expression: str) -> str:
    """Evaluate an arithmetic expression, e.g. "(2 + 3) * 4" or "sqrt(16) / 2".

    Supports + - * / // % **, parentheses, pi, e, and sqrt/abs/round/log/exp.
    """
    try:
        return str(evaluate(expression))
    except (ValueError, SyntaxError, ZeroDivisionError, OverflowError, TypeError) as exc:
        return f"Error: {exc}"


@tool
def current_time(timezone: str = "UTC") -> str:
    """Return the current date and time in ISO 8601 format for an IANA timezone such as "Europe/London"."""
    try:
        tz = ZoneInfo(timezone)
    except (ZoneInfoNotFoundError, ValueError):
        return f"Error: unknown timezone {timezone!r}"
    return datetime.now(tz).isoformat(timespec="seconds")


TOOLS = [calculator, current_time]

